func runBetaProcesses(t *testing.T) {
	apiKey := strings.TrimSpace(os.Getenv("ANTHROPIC_API_KEY"))
	if apiKey == "" {
		t.Fatal("ANTHROPIC_API_KEY is required for the beta live E2E")
