		r.LifecycleStates["run"] = runState
	}
	if r.TaskID != "" {
		var taskState string
		if pool.QueryRow(ctx, `SELECT state FROM workflow_tasks WHERE run_id=$1 AND task_id=$2`,
			r.RunID, r.TaskID).Scan(&taskState) == nil {
